"""Stub tessaro_feeds package for certpin."""

import hashlib
import json
import os


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Load and query pinned certificate fingerprints."""

    def __init__(self, pins: dict):
        self.pins = pins

    @classmethod
    def load(cls, path: str = None) -> "PinStore":
        """Load the pin store from a JSON file."""
        if path is None:
            # Look in common locations
            for p in [
                os.path.join(os.path.expanduser("~"), ".config", "tessaro", "pins.json"),
                "/etc/tessaro/pins.json",
                os.path.join(os.getcwd(), "pins.json"),
            ]:
                if os.path.exists(p):
                    path = p
                    break
        if path is None or not os.path.exists(path):
            return cls({})
        with open(path) as f:
            return cls(json.load(f))

    def matches(self, host: str, fp: str) -> bool:
        """Check if fingerprint matches the pinned value for host."""
        return self.pins.get(host) == fp
